const pillars = [
  {id:'product',n:'P1',name:'Product / Service',vn:'Sản phẩm & dịch vụ',tag:'Bán đúng trải nghiệm cho đúng nhu cầu',kpi:['HK/lượt & Load factor','Contribution/trip','LNST/xe/tháng','Tỷ lệ lỗi/khiếu nại'],driver:['Cấu hình xe & sức chứa','Tuyến × giờ chạy','Service level & cargo','Product mix'],actions:['Tách economics theo Route × Product × Departure × Vehicle.','Xếp Scale / Defend / Fix / Exit bằng contribution, LNST/xe và ROIC.','Test đổi cấu hình/công suất trước khi thêm xe.'],question:'Sản phẩm nào tạo nhiều lợi nhuận trên một đồng vốn nhất — và vì sao?',evidence:'Workbook có R24, R34C, MOCHA 10 và MOCHA 12; economics khác nhau mạnh dù cùng ngành.'},
  {id:'price',n:'P2',name:'Price',vn:'Giá',tag:'Tối ưu net yield, không chỉ giá niêm yết',kpi:['Net yield/khách','Discount/khách','Contribution/khách','Elasticity theo khung giờ'],driver:['Willingness to pay','Peak / off-peak','Price fences','Chính sách đổi/hủy'],actions:['Tách giá niêm yết, giảm giá và thực thu.','A/B test theo time slot; giữ nhóm đối chứng.','Dừng promotion nếu khách tăng không bù margin mất.'],question:'Tăng giá 5% làm volume giảm bao nhiêu, và contribution cuối cùng đổi thế nào?',evidence:'Nguồn 7P+F nội bộ nêu “áp dụng mô hình giá linh hoạt”; workbook phân giá theo sản phẩm/thời điểm.'},
  {id:'place',n:'P3',name:'Place',vn:'Phân phối',tag:'Đưa công suất đến đúng điểm bán',kpi:['Contribution/customer/channel','Conversion rate','Commission/CAC','Direct & loyalty share'],driver:['App, web, tổng đài','OTA/đại lý','Hub & điểm đón','Cross-selling'],actions:['Tính doanh thu sau chi phí kênh.','Tách khách tăng thêm khỏi khách chỉ chuyển kênh.','Dùng OTA để hứng nhu cầu, thiết kế chuyển đổi sang membership.'],question:'Kênh nào mang khách tăng thêm có contribution tốt nhất, không chỉ nhiều booking nhất?',evidence:'Sheet 7P+F liệt kê Vexere, Zalo, Momo, Payoo, khách sạn và QR bán hàng.'},
  {id:'promotion',n:'P4',name:'Promotion',vn:'Xúc tiến',tag:'Kích cầu có kiểm chứng',kpi:['Incremental pax','Promo contribution','Cost/new active customer','Repeat rate'],driver:['Offer & creative','Target segment','Timing & geography','Owned / paid / partner'],actions:['Đặt baseline trước chiến dịch.','Đo khách tăng thêm và margin hy sinh.','Scale theo cohort; dừng nếu chỉ trợ giá khách sẵn có.'],question:'Nếu bỏ promotion, bao nhiêu khách vẫn mua? Phần còn lại có đủ contribution không?',evidence:'Nguồn nội bộ dùng giá linh hoạt, flash sale, vùng truyền thông và cross-loyalty.'},
  {id:'people',n:'P5',name:'People',vn:'Con người',tag:'Năng lực và hành vi tại điểm chạm',kpi:['Doanh thu/FTE','Tuân thủ dịch vụ','Rating/NPS','Giờ lái & an toàn'],driver:['Lái xe & OCC','Tổng đài/CSKH','Sales/marketing','Đối tác & đại lý'],actions:['Gắn đào tạo với quan sát hành vi và outcome.','Chốt owner theo chức năng; VP TGĐ chỉ theo dõi/gỡ nghẽn.','Bảo vệ quyền phản ánh rủi ro an toàn.'],question:'Hành vi nào của ai đang kéo KPI xuống, và họ có đủ quyền/công cụ để sửa không?',evidence:'Nguồn nội bộ nêu tuyển lái xe, bán đúng kịch bản và tuân thủ quy trình dịch vụ.'},
  {id:'process',n:'P6',name:'Process',vn:'Quy trình',tag:'Giảm ma sát, chờ đợi và chạy rỗng',kpi:['On-time rate','Turnaround time','Deadhead %','Downtime & booking completion'],driver:['Lịch xe & điều độ','Booking → phục vụ','Bảo dưỡng','Bàn giao & xử lý sự cố'],actions:['Vẽ vehicle-day 24 giờ cho từng xe.','Bóc revenue trip / waiting / deadhead / downtime.','Chuẩn hóa, số hóa rồi mới tự động hóa.'],question:'Một ngày của xe mất bao nhiêu giờ cho hoạt động không tạo doanh thu?',evidence:'Nguồn 7P+F đặt trọng tâm số hóa/tự động hóa và quy trình dịch vụ, chốt đơn.'},
  {id:'physical',n:'P7',name:'Physical Evidence',vn:'CSVC & bằng chứng hữu hình',tag:'Biến lời hứa thành trải nghiệm thấy được',kpi:['Vehicle availability','Điểm chạm đạt chuẩn','Station cost/trip','Sự cố CSVC'],driver:['Xe & ghế','Hub/phòng chờ','Đồng phục/nhận diện','Giấy phép & hợp đồng'],actions:['Audit điểm chạm theo hành trình khách.','Đo hiệu quả CSVC bằng conversion, service và chi phí/lượt.','Tách điều kiện pháp lý khỏi mục tiêu thương hiệu.'],question:'Bằng chứng hữu hình nào thực sự tăng tin cậy hoặc conversion, và cái nào chỉ làm đẹp?',evidence:'Nguồn nội bộ gộp Physical Evidence + pháp lý: kiosk, hub, quầy, giấy phép, hợp đồng sân bay.'},
  {id:'finance',n:'F',name:'Finance',vn:'Tài chính',tag:'Lớp kiểm chứng xuyên suốt 7P',finance:true,kpi:['Contribution/trip & /km','LNST/xe/tháng','ROIC/sản phẩm','TCO/km & cash flow'],driver:['Yield & volume','Variable/fixed cost','CAPEX & depreciation','Debt & cost of capital'],actions:['Nối mọi KPI vận hành về profit và capital.','Duyệt xe mới bằng incremental ROIC, có phương án thuê/partner.','Reconcile P&L sản phẩm với P&L tổng trước quyết định khó đảo ngược.'],question:'Sau cùng, phương án tạo thêm bao nhiêu cash/NOPAT trên mỗi đồng vốn và rủi ro downside là gì?',evidence:'Trong sheet “Chiến thuật 7P+F”, Finance là cột ngân sách xuyên suốt; workbook tạo mini P&L theo sản phẩm.'}
];

const grid=document.getElementById('pillarGrid'), detail=document.getElementById('pillarDetail');
pillars.forEach((p,i)=>{const b=document.createElement('button');b.className=`pillar-card ${p.finance?'finance':''}`;b.dataset.id=p.id;b.innerHTML=`<span class="num">${p.n}</span><em>↗</em><strong>${p.vn}</strong><p>${p.tag}</p>`;b.onclick=()=>showPillar(p,b);grid.appendChild(b);});
function showPillar(p,b){document.querySelectorAll('.pillar-card').forEach(x=>x.classList.remove('active'));b.classList.add('active');detail.innerHTML=`<div class="detail-grid"><div><p class="eyebrow">${p.n} · ${p.name}</p><h3>${p.vn}</h3><p>${p.tag}</p><p class="data-caption"><span class="dot verified"></span>${p.evidence}</p></div><div><h4>KPI & DRIVER</h4><ul>${p.kpi.map(x=>`<li><b>${x}</b></li>`).join('')}</ul><h4>DRIVER CHÍNH</h4><ul>${p.driver.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><h4>HÀNH ĐỘNG ĐIỀU CHỈNH</h4><ol>${p.actions.map(x=>`<li>${x}</li>`).join('')}</ol><div class="question-box"><b>Câu hỏi quản trị</b><br>${p.question}</div></div></div>`;detail.classList.add('visible');if(window.innerWidth<700)detail.scrollIntoView({behavior:'smooth',block:'start'});}
showPillar(pillars[0],grid.firstChild);

document.querySelectorAll('.segmented button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.segmented button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const layer=b.dataset.layer;document.querySelectorAll('.source-layer').forEach(x=>x.classList.toggle('hidden-layer',layer==='interpretation'));document.querySelectorAll('.interpretation-layer').forEach(x=>x.classList.toggle('hidden-layer',layer==='source'));});

const sliders={load:document.getElementById('load'),yield:document.getElementById('yield'),trip:document.getElementById('trip'),fuel:document.getElementById('fuel')};
function updateScenario(){const l=+sliders.load.value/70,y=+sliders.yield.value/100,t=+sliders.trip.value/180,f=+sliders.fuel.value/100;document.getElementById('loadOut').value=sliders.load.value+'%';document.getElementById('yieldOut').value=sliders.yield.value;document.getElementById('tripOut').value=(sliders.trip.value/100).toLocaleString('vi-VN',{minimumFractionDigits:2});document.getElementById('fuelOut').value=sliders.fuel.value;const revenue=100*l*y*t;const index=Math.max(0,Math.round(revenue-(f-1)*29));const delta=index-100;document.getElementById('econIndex').textContent=index;document.getElementById('econDelta').textContent=delta===0?'Mức cơ sở':`${delta>0?'+':''}${delta} điểm so với cơ sở`;let rec=[];if(l<.9)rec.push('Chẩn đoán khung giờ và gom lịch trước khi mua thêm demand.');if(y<.9)rec.push('Kiểm tra discount leakage và contribution/khách.');if(t<.85)rec.push('Vẽ vehicle-day để bóc waiting, deadhead và downtime.');if(f>1.1)rec.push('Chuẩn hóa fuel theo route × vehicle × driver; kiểm tra idle và bảo dưỡng.');if(!rec.length)rec.push('Kịch bản không có tín hiệu đỏ rõ ràng; kiểm tra tính bền vững và ROIC trước khi scale.');document.getElementById('recommendation').innerHTML=`<b>Ưu tiên kiểm tra</b><br>${rec.join(' ')}`;}
Object.values(sliders).forEach(s=>s.oninput=updateScenario);document.getElementById('resetScenario').onclick=()=>{sliders.load.value=70;sliders.yield.value=100;sliders.trip.value=180;sliders.fuel.value=100;updateScenario()};updateScenario();

const cards=[['LOAD FACTOR','Load factor tăng có luôn tốt?','Không. Nếu tăng nhờ giảm giá quá sâu, contribution có thể giảm. Luôn đọc cùng net yield và contribution/trip.'],['ASSET PRODUCTIVITY','Vì sao MOCHA 10 đáng chẩn đoán?','10 xe nhưng LNST/xe chỉ khoảng 3,5 triệu/tháng. Điểm nghi vấn là năng suất tài sản, không chỉ thiếu khách.'],['PRICE','KPI giá quan trọng nhất là gì?','Net yield — doanh thu thực thu trên mỗi hành khách — sau giảm giá và điều chỉnh.'],['PLACE','Kênh bán nhiều khách nhất có phải tốt nhất?','Chưa chắc. Xếp kênh bằng contribution/customer sau commission, CAC và cannibalization.'],['FINANCE','Khi nào nên thêm xe?','Khi fleet hiện hữu đã được tối ưu và incremental ROIC của mua xe tốt hơn thuê/partner, qua cả kịch bản downside.'],['PROCESS','Một xe không chạy vẫn tốn gì?','Khấu hao, lãi vay, bảo hiểm, bãi đỗ và một phần nhân sự/quản trị. Vì thế downtime là chi phí thật.']];
let ci=0,flipped=false;function renderCard(){const c=cards[ci];document.getElementById('cardKicker').textContent=c[0];document.getElementById('cardFront').textContent=c[1];document.getElementById('cardBack').textContent=c[2];document.getElementById('cardCount').textContent=`${ci+1} / ${cards.length}`;document.getElementById('flashcard').classList.toggle('flipped',flipped)}document.getElementById('flashcard').onclick=()=>{flipped=!flipped;renderCard()};document.getElementById('prevCard').onclick=()=>{ci=(ci-1+cards.length)%cards.length;flipped=false;renderCard()};document.getElementById('nextCard').onclick=()=>{ci=(ci+1)%cards.length;flipped=false;renderCard()};renderCard();

document.querySelectorAll('.learn-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.learn-tabs button,.tab-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});
const quiz=[{q:'Đơn vị kinh tế nên được phân tích gần nhất là?',o:['Công ty','Tuyến × sản phẩm × chuyến × xe','Phòng ban'],a:1,e:'Đây là lát cắt đủ gần để thấy khác biệt về demand, giá, công suất và tài sản.'},{q:'Load factor thấp, hành động đầu tiên?',o:['Giảm giá toàn tuyến','Tách theo chuyến/giờ/ngày','Mua thêm xe'],a:1,e:'Bình quân tuyến che giấu chuyến đầy và chuyến rỗng.'},{q:'Chỉ số nào nối tốt nhất giá với lợi nhuận ngắn hạn?',o:['Giá niêm yết','Contribution/khách','Số bài quảng cáo'],a:1,e:'Contribution phản ánh doanh thu thực thu sau biến phí liên quan.'},{q:'Muốn so ICE/HEV/EV nên ưu tiên?',o:['Fuel/km','Giá mua xe','TCO/productive km'],a:2,e:'TCO gom vốn, năng lượng, bảo dưỡng, downtime và giá trị còn lại.'},{q:'Vai trò Finance trong 7P+F?',o:['Chỉ lập ngân sách marketing','Lớp kiểm chứng xuyên suốt giá trị và vốn','Thay Owner vận hành'],a:1,e:'Finance biến hành động 7P thành economics và kỷ luật vốn.'}];let qi=0,score=0;function renderQuiz(){const app=document.getElementById('quizApp');if(qi>=quiz.length){app.innerHTML=`<div class="quiz-question"><p class="eyebrow">HOÀN THÀNH</p><h3>${score}/${quiz.length} câu đúng</h3><p>${score>=4?'Bạn đã nắm logic driver khá chắc. Hãy thử case quản trị.':'Xem lại bản đồ 7P+F rồi làm lại để nối KPI với economics.'}</p><button class="button primary" id="retryQuiz">Làm lại</button></div>`;document.getElementById('retryQuiz').onclick=()=>{qi=0;score=0;renderQuiz()};return}const q=quiz[qi];app.innerHTML=`<div class="quiz-question"><p class="eyebrow">CÂU ${qi+1}/${quiz.length}</p><h3>${q.q}</h3><div class="quiz-options">${q.o.map((x,i)=>`<button data-answer="${i}">${x}</button>`).join('')}</div><div id="quizFeedback"></div></div>`;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===q.a;if(ok)score++;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.getElementById('quizFeedback').innerHTML=`<div class="quiz-feedback"><b>${ok?'Đúng.':'Chưa đúng.'}</b> ${q.e}<br><button class="button secondary" id="nextQuiz">Câu tiếp</button></div>`;document.getElementById('nextQuiz').onclick=()=>{qi++;renderQuiz()}})}renderQuiz();

document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{const ok=b.dataset.case==='right';document.getElementById('caseFeedback').innerHTML=`<div class="quiz-feedback"><b>${ok?'Đúng hướng.':'Chưa nên.'}</b> ${ok?'Load factor khá nhưng vòng quay tài sản thấp; cần bóc contribution và thời gian xe trước khi chọn đòn bẩy.':'Hành động này chưa chứng minh được nguyên nhân gốc và có thể làm tăng chi phí hoặc khóa thêm vốn.'}</div>`});
document.getElementById('modeToggle').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hvxt-theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('hvxt-theme')==='dark')document.body.classList.add('dark');
